sys_script_client.script:
function onLoad() { //MSSCUSTODY-3543

    var existingValue = g_form.getValue('outcome'); //stores the existing outcome values.
    g_form.clearOptions('outcome');
    g_form.addOption('outcome', '', '-- None --');

    if (existingValue) {
        //g_form.setValue('outcome', existingValue); //if exixsting value is present add it to outome field..
        if (typeof(g_aw) != 'undefined') {
            //console.log('go for workspace');
            g_form.addOption('outcome', existingValue, existingValue);
        }
        //For Classic View
        else {
            // console.log('go for classic view');
            g_form.setValue('outcome', existingValue);
        }
    }

    var ga = new GlideAjax('x_hsb11_mss_c_proc.MSSCustodyBulkUtils');
    ga.addParam('sysparm_name', 'evalBulkoutcome');
    ga.addParam('sysparm_sys_id', g_form.getUniqueValue());
    ga.getXMLAnswer(outcomesParse);

    function outcomesParse(response) {
        var outcomesArr = JSON.parse(response);
        for (var i = 0; i < outcomesArr.length; i++) {
            g_form.addOption('outcome', outcomesArr[i].value, outcomesArr[i].displayValue);

            var bulkType = g_scratchpad.bulktype;
            if (bulkType == "automated_task" && g_scratchpad.tradelifecycle == 'TradToBeMtchdNtrnly') { // MSSCUSTODY-3939 remove outcomes for trade matched internally
                g_form.removeOption('outcome', "Corresponding Switch trade identified in 'Trade on Hold' status");
                g_form.removeOption('outcome', "No remediation of corresponding Switch trade possible - put each 'Trade on Hold'");
            }

            // MSSCUSTODY-6379

            var arrSwiftStatus = ['MT540capture_request', 'MT541capture_request', 'MT542capture_request', 'MT543capture_request', 'MT540cancel_request', 'MT541cancel_request', 'MT542cancel_request', 'MT543cancel_request', 'MT544settlement_confirmation', 'MT545settlement_confirmation', 'MT546settlement_confirmation', 'MT547settlement_confirmation', 'MT544settlement_confirmation_reversal', 'MT545settlement_confirmation_reversal', 'MT546settlement_confirmation_reversal', 'MT547settlement_confirmation_reversal', 'MT548status_advice', 'MT548cancellation_status_advice'];

            if (bulkType == "automated_task" && arrSwiftStatus.includes(g_scratchpad.tradelifecycle)) {
                if (outcomesArr[i].value.toLowerCase().indexOf('to not be processed') > 1) {
                    g_form.setValue('outcome', outcomesArr[i].value, outcomesArr[i].displayValue);
                    g_form.setReadOnly('outcome', true);
                    g_form.setMandatory('comments', true);
                }
            }
        }
    }
}
